// Door 1: the in-page API. A JS cell runs on the app page, so it can
// introspect the very notebook it lives in. (Read-only here on purpose -
// runAndSave would replace the notebook you are reading.)
const api = window.NotebookLabAPI;
if (!api) return 'NotebookLabAPI not found - is the app fully loaded?';

const current = await api.getCurrentNotebook();

const kinds = {};
for (const cell of current.cells) kinds[cell.kind] = (kinds[cell.kind] || 0) + 1;

console.log('this notebook, as seen through its own API:');
console.log('  title:', current.title);
console.log('  cells:', current.cells.length, JSON.stringify(kinds));

return {
  title: current.title,
  cellCount: current.cells.length,
  cellKinds: kinds,
  apiVersion: api.version,
};

// Build (and sanity-check) a command object for the file inbox.
// This cell only CONSTRUCTS it - copy the printed JSON into a file in
// api/inbox/ to actually execute it.
const command = {
  version: 'notebook-lab-api-v1',
  requestId: 'demo-' + Date.now().toString(36),
  action: 'runAndSave',
  notebook: {
    title: 'API-Built Notebook',
    cells: [
      { kind: 'md', source: '# Built by a command file\n\nEvery cell below ran headlessly.' },
      { kind: 'js', source: "nb.set('answer', 6 * 7); console.log('js says', nb.get('answer'));" },
      { kind: 'py', source: "print('python says', nb.get('answer'))" },
    ],
  },
  run: { mode: 'all', stopOnError: false },
  save: { persistNotebook: true, writeResultManifest: true },
};

// Light validation mirroring apiProtocol.js expectations.
const problems = [];
if (!command.notebook.cells.length) problems.push('notebook has no cells');
if (!['loadNotebook', 'runNotebook', 'saveNotebook', 'runAndSave'].includes(command.action))
  problems.push('unknown action');
console.log(problems.length ? 'INVALID: ' + problems.join('; ') : 'command looks valid');
console.log(JSON.stringify(command, null, 2));

return 'Copy the JSON above into <data-root>/notebook-lab/api/inbox/demo.json to run it.';
